qs.append({"q":"The recommendations of the Third Round Table Conference were published in a White Paper in March 1933, eventually leading, via a Joint Select Committee's draft Bill, to which major legislation enacted in July 1935?","o":["The Government of India Act, 1935","The Government of India Act, 1919","The Indian Councils Act, 1909","The Rowlatt Act"],"a":0,"e":"The Third RTC's deliberations culminated in the Government of India Act, 1935, based on a Joint Select Committee's draft Bill produced in February 1935."})

